      if (c == ':') { adv(); return {TK::Colon, ":", line}; }
      if (c == '{') { adv(); return {TK::LBrace,    "{", line}; }
      if (c == '}') { adv(); return {TK::RBrace,    "}", line}; }
      if (c == '.') { adv(); return {TK::Dot,       ".", line}; }
      if (c == ',') { adv(); return {TK::Comma,     ",", line}; }
      if (c == ';') { adv(); return {TK::Semicolon, ";", line}; }
